    static func tr(
        _ lang: AppLanguage,
        de: String,
        en: String,
        fr: String,
        es: String,
        pt: String,
        ru: String,
        ja: String,
        zh: String,
        nl: String? = nil,
        af: String? = nil,
        pl: String? = nil,
        cs: String? = nil,
        sk: String? = nil,
        hu: String? = nil,
        ko: String? = nil,
        hi: String? = nil,
        ta: String? = nil
    ) -> String {
        switch lang {
        case .de: return de
        case .en: return en
        case .fr: return fr
        case .es: return es
        case .pt: return pt
        case .ru: return ru
        case .ja: return ja
        case .zh: return zh
        case .nl: return nl ?? L10nExtendedCatalog.translate(.nl, de: de, en: en)
        case .af: return af ?? L10nExtendedCatalog.translate(.af, de: de, en: en)
        case .pl: return pl ?? L10nExtendedCatalog.translate(.pl, de: de, en: en)
        case .cs: return cs ?? L10nExtendedCatalog.translate(.cs, de: de, en: en)
        case .sk: return sk ?? L10nExtendedCatalog.translate(.sk, de: de, en: en)
        case .hu: return hu ?? L10nExtendedCatalog.translate(.hu, de: de, en: en)
        case .ko: return ko ?? L10nExtendedCatalog.translate(.ko, de: de, en: en)
        case .hi: return hi ?? L10nExtendedCatalog.translate(.hi, de: de, en: en)
        case .ta: return ta ?? L10nExtendedCatalog.translate(.ta, de: de, en: en)
        }
    }

    static func tabShorttip(_ tab: NavigationTab, _ lang: AppLanguage) -> String {
        switch tab {
        case .imageStudio: return GS.t("img_queue_hint", lang)
        case .overview: return text("tip_tab_overview", lang)
        case .devices: return text("tip_tab_devices", lang)
        case .models: return text("tip_tab_models", lang)
        case .network: return text("tip_tab_network", lang)
        case .internetCluster: return text("tip_tab_internet", lang)
        case .multiModelMode: return text("tip_tab_mmm", lang)
        case .agents: return text("tip_tab_agents", lang)
        case .science: return text("tip_tab_science", lang)
        case .console: return text("tip_tab_console", lang)
        case .setup: return text("tip_tab_setup", lang)
        case .help: return text("tip_tab_help", lang)
        }
    }

    static func readinessLabel(_ state: ClusterReadinessState, _ lang: AppLanguage) -> String {
        switch state {
        case .ready: return text("readiness_ready", lang)
        case .notReady: return text("readiness_not_ready", lang)
        case .incomplete: return text("readiness_incomplete", lang)
        case .unconfigured: return text("readiness_unconfigured", lang)
        }
    }
}

