    private struct InterpRule: @unchecked Sendable {
        let regex: NSRegularExpression
        let templates: [AppLanguage: String]
    }

    private static func buildInterpChunk0() -> [InterpRule] {
        var rules: [InterpRule] = []
        if let rx = try? NSRegularExpression(pattern: "^Worker\\ \\(Rank\\ (.*)\\)$", options: [.dotMatchesLineSeparators]) {
            rules.append(InterpRule(regex: rx, templates: [.nl: "Worker (Rang $1)", .af: "Werker (Rang $1)", .pl: "Worker (Ranga $1)", .cs: "Worker (Pořadí $1)", .sk: "Worker (Poradie $1)", .hu: "Munkacsomópont (Rang $1)", .ko: "워커 (순위 $1)", .hi: "वर्कर (रैंक $1)", .ta: "பணியாளர் (வரிசை $1)"]))
        }
        if let rx = try? NSRegularExpression(pattern: "^Local\\ GGUF\\ file\\ \\((.*)\\)$", options: [.dotMatchesLineSeparators]) {
            rules.append(InterpRule(regex: rx, templates: [.nl: "Lokaal GGUF-bestand ($1)", .af: "Plaaslike GGUF-lêer ($1)", .pl: "Lokalny plik GGUF ($1)", .cs: "Místní soubor GGUF ($1)", .sk: "Miestny súbor GGUF ($1)", .hu: "Helyi GGUF-fájl ($1)", .ko: "로컬 GGUF 파일 ($1)", .hi: "स्थानीय GGUF फ़ाइल ($1)", .ta: "உள்ளூர் GGUF கோப்பு ($1)"]))
        }
        if let rx = try? NSRegularExpression(pattern: "^Copied\\ oMLX\\ launch\\ command\\ \\(Paged\\ SSD\\ KV\\ Cache\\ active\\):\\ (.*)$", options: [.dotMatchesLineSeparators]) {
