            rules.append(InterpRule(regex: rx, templates: [.nl: "Geschiedenis gekopieerd als CSV ($1 vermeldingen).", .af: "Geskiedenis as CSV gekopieer ($1 inskrywings).", .pl: "Skopiowano historię jako CSV ($1 wpisów).", .cs: "Historie zkopírována jako CSV ($1 záznamů).", .sk: "História skopírovaná ako CSV ($1 záznamov).", .hu: "Előzmények másolva CSV-ként ($1 bejegyzés).", .ko: "기록이 CSV로 복사됨 ($1개 항목).", .hi: "इतिहास CSV के रूप में कॉपी किया गया ($1 प्रविष्टियाँ)।", .ta: "வரலாறு CSV ஆக நகலெடுக்கப்பட்டது ($1 பதிவுகள்)."]))
        }
        if let rx = try? NSRegularExpression(pattern: "^(.*?)\\ /\\ (.*)\\ entries$", options: [.dotMatchesLineSeparators]) {
            rules.append(InterpRule(regex: rx, templates: [.nl: "$1 / $2 vermeldingen", .af: "$1 / $2 inskrywings", .pl: "$1 / $2 wpisów", .cs: "$1 / $2 záznamů", .sk: "$1 / $2 záznamov", .hu: "$1 / $2 bejegyzés", .ko: "$1 / $2 항목", .hi: "$1 / $2 प्रविष्टियाँ", .ta: "$1 / $2 பதிவுகள்"]))
        }
        if let rx = try? NSRegularExpression(pattern: "^Time\\ Series\\ \\((.*)\\)$", options: [.dotMatchesLineSeparators]) {
            rules.append(InterpRule(regex: rx, templates: [.nl: "Tijdreeks ($1)", .af: "Tydreeks ($1)", .pl: "Szereg czasowy ($1)", .cs: "Časová řada ($1)", .sk: "Časový rad ($1)", .hu: "Idősor ($1)", .ko: "시계열 ($1)", .hi: "समय श्रृंखला ($1)", .ta: "காலத் தொடர் ($1)"]))
        }
        if let rx = try? NSRegularExpression(pattern: "^Recorded\\ Data\\ Points\\ \\((.*)\\)$", options: [.dotMatchesLineSeparators]) {
            rules.append(InterpRule(regex: rx, templates: [.nl: "Geregistreerde meetpunten ($1)", .af: "Aangetekende datapunte ($1)", .pl: "Zarejestrowane punkty danych ($1)", .cs: "Zaznamenané datové body ($1)", .sk: "Zaznamenané dátové body ($1)", .hu: "Rögzített adatpontok ($1)", .ko: "기록된 데이터 포인트 ($1)", .hi: "दर्ज किए गए डेटा बिंदु ($1)", .ta: "பதிவுசெய்யப்பட்ட தரவுப் புள்ளிகள் ($1)"]))
        }
        return rules
    }

    private static let interpRules: [InterpRule] = {
        var all: [InterpRule] = []
        all.append(contentsOf: buildInterpChunk0())
        all.append(contentsOf: buildInterpChunk1())
        all.append(contentsOf: buildInterpChunk2())
        return all
    }()

    static func translate(_ lang: AppLanguage, de: String, en: String) -> String {
        let chunks: [[String: String]]
        switch lang {
        case .nl: chunks = nlChunks
        case .af: chunks = afChunks
        case .pl: chunks = plChunks
        case .cs: chunks = csChunks
        case .sk: chunks = skChunks
        case .hu: chunks = huChunks
        case .ko: chunks = koChunks
        case .hi: chunks = hiChunks
        case .ta: chunks = taChunks
        default: return en
        }

        for dict in chunks {
            if let hit = dict[en] {
                return hit
            }
        }

        let nsEn = en as NSString
        let fullRange = NSRange(location: 0, length: nsEn.length)
        for rule in interpRules {
            if let match = rule.regex.firstMatch(in: en, options: [], range: fullRange),
               let template = rule.templates[lang] {
                var result = template
                // Replace $N down to $1 so $10 never collides with $1
                for idx in stride(from: match.numberOfRanges - 1, through: 1, by: -1) {
                    let r = match.range(at: idx)
                    let val = r.location != NSNotFound ? nsEn.substring(with: r) : ""
                    result = result.replacingOccurrences(of: "$\(idx)", with: val)
                }
                return result
            }
        }
        return en
    }
}
